<script setup lang="ts">
import {nodeDisplayName} from '../nodePresentation'
import UiSelect from './UiSelect.vue'
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {api,request,saveFile} from '../api'
import {useWorkspace} from '../workspace'
import {date,stateLabel,type LatencyBatch,type MonitorSample,type NodeOption} from '../domain'
import Icon from './Icon.vue'
import Modal from './Modal.vue'
const w=useWorkspace(),tab=ref('batch'),batch=ref<LatencyBatch|null>(null),loading=ref(false),error=ref(''),nodeId=ref(''),profile=ref(''),target=ref(''),identity=ref(''),cursor=ref(''),hasMore=ref(false),samples=ref<MonitorSample[]>([]),facets=ref<{nodes:{node_key:string;node_identity_key:string;profile_id:string;display_name:string}[];profiles:string[];targets:string[]}>({nodes:[],profiles:[],targets:[]}),legacy=ref<Record<string,any>[]>([]),legacyDetail=ref<Record<string,any>|null>(null)
let generation=0;const until=ref(new Date().toISOString()),since=computed(()=>new Date(Date.parse(until.value)-w.hours.value*3600000).toISOString())
async function refresh(){loading.value=true;error.value='';const gen=++generation,mode=tab.value;try{
  if(mode==='batch'){const result=await api.batches();if(gen===generation)w.batches.value=result||[]}
  if(mode==='monitor'){samples.value=[];cursor.value='';hasMore.value=false;until.value=new Date().toISOString();const result=await api.monitorFacets(since.value,until.value);if(gen!==generation)return;facets.value=result;await readSamples(false)}
  if(mode==='legacy'){const result=await request<Record<string,any>[]>('/api/history','GET',undefined,'ListHistory');if(gen===generation)legacy.value=result||[]}
}catch(e){if(gen===generation)error.value=e instanceof Error?e.message:String(e)}finally{if(gen===generation)loading.value=false}}
async function readSamples(append=false){error.value='';loading.value=true;const gen=++generation;if(!append){samples.value=[];cursor.value='';hasMore.value=false}try{const result=await api.monitorSamples({since:since.value,until:until.value,profile_id:profile.value,node_identity_key:identity.value,target:target.value,cursor:append?cursor.value:undefined,limit:100,order_desc:true});if(gen!==generation)return;samples.value=append?[...samples.value,...(result.items||[])]:result.items||[];cursor.value=result.next_cursor;hasMore.value=result.has_more}catch(e){if(gen===generation)error.value=e instanceof Error?e.message:String(e)}finally{if(gen===generation)loading.value=false}}
let detailGeneration=0
function closeDetails(){detailGeneration++;batch.value=null;legacyDetail.value=null}
async function openBatch(id:string){const token=++detailGeneration;try{const result=await api.batch(id);if(token===detailGeneration)batch.value=result}catch(e){if(token===detailGeneration)w.fail(e)}}
async function retryBatchItem(id:string){if(!batch.value)return;const token=detailGeneration,batchId=batch.value.batch_id;try{const result=await api.retryBatch(batchId,id);if(token!==detailGeneration||batch.value?.batch_id!==batchId)return;batch.value=result;w.absorbBatch(result)}catch(e){if(token===detailGeneration)w.fail(e)}}
function detailFromItem(item:NonNullable<LatencyBatch['items']>[number]):NodeOption{return {...item,display_name:item.display_name,profile_name:w.nodes.value.find(n=>n.profile_id===item.profile_id)?.profile_name||'历史订阅',type:item.result?.node_type||'',country_code:'',country_flag:''}}
async function openLegacy(id:string){const token=++detailGeneration;try{const result=await request<Record<string,any>>(`/api/history/${encodeURIComponent(id)}`,'GET',undefined,'GetHistory',[id]);if(token===detailGeneration)legacyDetail.value=result}catch(e){if(token===detailGeneration)w.fail(e)}}
function openNode(){const n=w.nodes.value.find(n=>n.profile_id+'|'+n.node_key===nodeId.value);if(n)w.inspectNode.value=n}
watch(profile,()=>{identity.value=''},{flush:'sync'});watch(tab,()=>{closeDetails();void refresh()},{immediate:true});watch([profile,target,identity,()=>w.hours.value],()=>{if(tab.value==='monitor'){until.value=new Date().toISOString();void readSamples(false)}})
onBeforeUnmount(()=>{generation++;detailGeneration++})
</script>
<template><section class="page-view"><div class="page-header"><div><h1>检测历史</h1><p>查看已保存的检测、采样和历史配置。</p></div><button class="button ghost" :disabled="loading" @click="refresh"><Icon name="refresh"/>刷新</button></div><nav class="project-tabs"><button v-for="[id,label] in [['batch','批量检测'],['node','节点记录'],['monitor','持续监测'],['legacy','旧版记录']]" :key="id" :aria-selected="tab===id" @click="tab=id">{{label}}</button></nav><p v-if="error" class="inline-error" role="alert">{{error}}</p><div v-if="tab==='batch'" class="history-batches"><button v-for="b in w.batches.value" :key="b.batch_id" class="history-batch-row" @click="openBatch(b.batch_id)"><span class="history-symbol"><Icon name="pulse"/></span><span><strong>{{b.target_id==='all'?'六站延迟检测':'延迟检测'}} · {{b.item_count}} 个节点</strong><small>{{date(b.requested_at)}}<template v-if="b.sample_count"> · 计划每站 {{b.sample_count}} 次</template></small></span><span class="badge" :class="b.state==='completed'?'good':''">{{stateLabel(b.state)}}</span><Icon name="chevron"/></button><div v-if="!loading&&!w.batches.value.length" class="empty-state">还没有批量检测记录。</div></div><div v-if="tab==='node'" class="settings-section"><h2>按节点查看三类检测</h2><p class="muted">延迟、下载和服务记录在节点详情中切换。</p><div class="inline-field"><UiSelect v-model="nodeId" aria-label="选择历史节点"><option value="">选择节点</option><option v-for="n in w.nodes.value" :key="n.profile_id+n.node_key" :value="n.profile_id+'|'+n.node_key">{{n.profile_name}} · {{nodeDisplayName(n)}}</option></UiSelect><button class="button primary" :disabled="!nodeId" @click="openNode">查看记录</button></div></div><template v-if="tab==='monitor'"><div class="history-filter-row"><label>历史范围<UiSelect v-model.number="w.hours.value"><option :value="6">最近 6 小时</option><option :value="24">最近 24 小时</option><option :value="168">最近 7 天</option><option :value="720">最近 30 天</option></UiSelect></label><label>订阅<UiSelect v-model="profile"><option value="">全部订阅</option><option v-for="id in facets.profiles" :key="id" :value="id">{{w.nodes.value.find(n=>n.profile_id===id)?.profile_name||id}}</option></UiSelect></label><label>节点<UiSelect v-model="identity"><option value="">全部节点</option><option v-for="n in facets.nodes.filter(n=>!profile||n.profile_id===profile)" :key="n.profile_id+n.node_identity_key+n.node_key" :value="n.node_identity_key">{{nodeDisplayName(n)}}</option></UiSelect></label><label>目标<UiSelect v-model="target"><option value="">全部目标</option><option v-for="t in facets.targets" :key="t" :value="t">{{t}}</option></UiSelect></label><button class="button ghost" @click="saveFile(JSON.stringify(samples,null,2),'speedtest-monitor-samples.json','application/json').then(saved=>{if(saved)w.notify('样本已导出')}).catch(w.fail)">导出已读样本</button></div><div class="table-scroll"><table><thead><tr><th>时间</th><th>节点</th><th>目标</th><th>采样类型</th><th>延迟</th><th>结果</th></tr></thead><tbody><tr v-for="s in samples" :key="s.sample_id"><td class="nowrap">{{date(s.timestamp)}}</td><td>{{nodeDisplayName({display_name:s.display_name_snapshot})}}<small>配置 {{s.config_revision_key?.slice(-8)||'旧版'}}</small></td><td class="break-text">{{s.target}}</td><td>{{s.sampling_tier==='regular'?'常规':s.sampling_tier==='focus'?'重点':s.sampling_tier==='sparse'?'稀疏':s.sampling_tier==='diagnostic'?'手动诊断':'旧版'}}<small>{{s.probe_type}}</small></td><td>{{s.success?`${(s.latency/1e6).toFixed(0)} ms`:'—'}}</td><td :class="s.success?'good':'bad'">{{s.success?'成功':s.error_class||'失败'}}<small v-if="s.error_detail">{{s.error_detail}}</small></td></tr></tbody></table></div><div v-if="!samples.length&&!loading&&!error" class="empty-state">这个范围没有监测样本。</div><button v-if="hasMore" class="button" :disabled="loading" @click="readSamples(true)">{{loading?'读取中…':'读取更早样本'}}</button></template><div v-if="tab==='legacy'" class="history-batches"><button v-for="r in legacy" :key="r.id" class="history-batch-row" @click="openLegacy(r.id)"><span class="history-symbol"><Icon name="history"/></span><span><strong>{{r.airport_name||'旧版测速'}} · {{r.total_nodes||r.node_count||0}} 个节点</strong><small>{{date(r.created_at)}}</small></span><Icon name="chevron"/></button><div v-if="!legacy.length&&!loading" class="empty-state">没有旧版测速记录。</div></div><div v-if="loading" class="loading-state">读取记录中…</div><Modal v-if="batch" title="批次记录" wide @close="closeDetails"><p class="muted">{{date(batch.requested_at)}} · {{batch.item_count}} 个节点 · {{stateLabel(batch.state)}}</p><div v-for="item in batch.items" :key="item.item_id" class="compact-row"><button class="text-button" @click="w.inspectNode.value=detailFromItem(item);closeDetails()">{{nodeDisplayName(item)}}</button><div class="button-group"><span>{{stateLabel(item.execution_state)}} · {{stateLabel(item.persistence_state)}}</span><button v-if="item.persistence_state==='failed'" class="text-button" @click="retryBatchItem(item.item_id)">重试保存</button></div><p v-if="item.result" class="small muted">实际采样 {{item.result.total_samples}} 次 · 成功 {{item.result.success_samples}} 次</p><p v-if="item.error_message||item.persistence_error" class="bad small">{{item.error_message||item.persistence_error}}</p></div></Modal><Modal v-if="legacyDetail" title="旧版测速记录" wide @close="closeDetails"><pre class="record-json">{{JSON.stringify(legacyDetail,null,2)}}</pre><template #footer><button class="button" @click="saveFile(JSON.stringify(legacyDetail,null,2),'speedtest-legacy-history.json','application/json').then(saved=>{if(saved)w.notify('记录已导出')}).catch(w.fail)">导出原始记录</button></template></Modal></section></template>
